# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.86.0/ankra-cli-darwin-arm64"
      sha256 "4d169237a8f3a445ff08fccf952fd6b32e14f88e5a44601a6b4477a0dbec5a04"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.86.0/ankra-cli-darwin-amd64"
      sha256 "b9b734786ba50bc1945800bd8c00043d345088a5b178dbe237e68467d1d79c68"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.86.0/ankra-cli-linux-arm64"
      sha256 "707a3bdbb3ce09cf15c5fa836a30fe1f414290ff8f10106a6e70e77f89bb4ae2"
    end
    on_intel do
